create table if not exists public.exchange_rates(exchange_rate_id bigint generated always as identity primary key,from_currency_id bigint not null references public.currencies(currency_id),to_currency_id bigint not null references public.currencies(currency_id),effective_date date not null,spot_rate numeric(24,10) not null check(spot_rate>0),unique(from_currency_id,to_currency_id,effective_date),check(from_currency_id<>to_currency_id));
create table if not exists public.fiscal_periods(fiscal_period_id bigint generated always as identity primary key,period_name text not null,start_date date not null,end_date date not null,is_closed boolean not null default false,fiscal_year_id bigint not null references public.fiscal_years(fiscal_year_id),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),unique(fiscal_year_id,subsidiary_id,period_name),check(end_date>=start_date));
create table if not exists public.consolidated_exchange_rates(rate_id bigint generated always as identity primary key,from_currency_id bigint not null references public.currencies(currency_id),to_currency_id bigint not null references public.currencies(currency_id),fiscal_period_id bigint not null references public.fiscal_periods(fiscal_period_id),average_rate numeric(24,10) not null check(average_rate>0),current_rate numeric(24,10) not null check(current_rate>0),historical_rate numeric(24,10) not null check(historical_rate>0),unique(from_currency_id,to_currency_id,fiscal_period_id),check(from_currency_id<>to_currency_id));
create table if not exists public.payment_terms(term_id bigint generated always as identity primary key,term_name text not null unique,days_due integer not null default 0 check(days_due>=0),discount_days integer not null default 0 check(discount_days>=0),discount_percentage numeric(7,4) not null default 0 check(discount_percentage between 0 and 100));
create table if not exists public.payment_methods(payment_method_id bigint generated always as identity primary key,method_name text not null unique,is_credit_card boolean not null default false,is_bank_transfer boolean not null default false);
create table if not exists public.uom(uom_id bigint generated always as identity primary key,unit_code text not null unique,name text not null,symbol text not null);
create table if not exists public.tax_agencies(tax_agency_id bigint generated always as identity primary key,agency_name text not null,country_id bigint not null references public.countries(country_id),subsidiary_id bigint references public.subsidiaries(subsidiary_id),tax_id text not null,unique(country_id,tax_id));
create table if not exists public.tax_types(tax_type_id bigint generated always as identity primary key,country_id bigint not null references public.countries(country_id),type_name text not null,unique(country_id,type_name));
create table if not exists public.tax_codes(tax_code_id bigint generated always as identity primary key,code_name text not null,rate_percentage numeric(9,5) not null check(rate_percentage between 0 and 100),is_withholding boolean not null default false,country_id bigint not null references public.countries(country_id),tax_agency_id bigint not null references public.tax_agencies(tax_agency_id),tax_type_id bigint not null references public.tax_types(tax_type_id),subsidiary_id bigint references public.subsidiaries(subsidiary_id),unique(code_name,country_id,subsidiary_id));
create table if not exists public.tax_groups(tax_group_id bigint generated always as identity primary key,group_code text not null,group_name text not null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),unique(group_code,subsidiary_id));
create table if not exists public.series(series_id bigint generated always as identity primary key,series_name text not null,prefix text,current_number bigint not null default 0 check(current_number>=0),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),transaction_type_id bigint not null references public.transaction_types(transaction_type_id),unique(series_name,subsidiary_id,transaction_type_id));
create table if not exists public.document_types(document_type_id bigint generated always as identity primary key,type_code text not null,type_name text not null,country_id bigint not null references public.countries(country_id),unique(type_code,country_id));
create table if not exists public.holidays(holiday_id bigint generated always as identity primary key,holiday_date date not null,description text not null,country_id bigint not null references public.countries(country_id),subsidiary_id bigint references public.subsidiaries(subsidiary_id),unique(holiday_date,country_id,subsidiary_id));
do $$ declare target_table text; begin foreach target_table in array array['exchange_rates','fiscal_periods','consolidated_exchange_rates','payment_terms','payment_methods','uom','tax_agencies','tax_types','tax_codes','tax_groups','series','document_types','holidays'] loop execute format('alter table public.%I enable row level security',target_table);execute format('drop policy if exists "configuration_select" on public.%I',target_table);execute format('drop policy if exists "configuration_insert" on public.%I',target_table);execute format('drop policy if exists "configuration_update" on public.%I',target_table);execute format('drop policy if exists "configuration_delete" on public.%I',target_table);execute format('create policy "configuration_select" on public.%I for select to authenticated using(true)',target_table);execute format('create policy "configuration_insert" on public.%I for insert to authenticated with check(true)',target_table);execute format('create policy "configuration_update" on public.%I for update to authenticated using(true) with check(true)',target_table);execute format('create policy "configuration_delete" on public.%I for delete to authenticated using(true)',target_table);end loop;end $$;
